export type MarkdownEditorMention = TriggerMenuItemData & { href: string };
type EditorSuggestion = TriggerMenuItemData & { href?: string; command?: (chain: ChainedCommands) => ChainedCommands };

function blockCommands(labels: MarkdownEditorLabels): readonly EditorSuggestion[] {
  return [
    {
      id: "paragraph",
      label: labels.text,
      keywords: ["paragraph"],
      icon: <TextIcon />,
      command: (chain) => chain.clearNodes().setParagraph(),
    },
    {
      id: "heading-1",
      label: labels.heading(1),
      keywords: ["h1", "title"],
      icon: <Heading1Icon />,
      command: (chain) => chain.clearNodes().setHeading({ level: 1 }),
    },
    {
      id: "heading-2",
      label: labels.heading(2),
      keywords: ["h2", "subtitle"],
      icon: <Heading2Icon />,
      command: (chain) => chain.clearNodes().setHeading({ level: 2 }),
    },
    {
      id: "heading-3",
      label: labels.heading(3),
      keywords: ["h3"],
      icon: <Heading3Icon />,
      command: (chain) => chain.clearNodes().setHeading({ level: 3 }),
    },
    { id: "bullet-list", label: labels.bulletList, icon: <ListIcon />, command: (chain) => chain.clearNodes().toggleBulletList() },
    {
      id: "ordered-list",
      label: labels.orderedList,
      keywords: ["ordered"],
      icon: <ListOrderedIcon />,
      command: (chain) => chain.clearNodes().toggleOrderedList(),
    },
    {
      id: "task-list",
      label: labels.taskList,
      keywords: ["todo", "checklist"],
      icon: <ListChecksIcon />,
      command: (chain) => chain.clearNodes().toggleTaskList(),
    },
    {
      id: "quote",
      label: labels.quote,
      keywords: ["blockquote"],
      icon: <QuoteIcon />,
      command: (chain) => chain.clearNodes().toggleBlockquote(),
    },
    { id: "code-block", label: labels.codeBlock, icon: <SquareCodeIcon />, command: (chain) => chain.clearNodes().setCodeBlock() },
    {
      id: "divider",
      label: labels.divider,
      keywords: ["rule", "separator"],
      icon: <MinusIcon />,
      command: (chain) => chain.setHorizontalRule(),
    },
    {
      id: "table",
      label: labels.table,
      keywords: ["grid", "columns"],
      icon: <TableIcon />,
      command: (chain) => chain.insertTable({ rows: 3, cols: 3, withHeaderRow: true }),
    },
  ];
}

function readTrigger(editor: Editor) {
  const { selection } = editor.state;
  const { $from } = selection;
  if (
    !editor.isFocused ||
    !selection.empty ||
    !$from.parent.isTextblock ||
    $from.parent.type.spec.code ||
    editor.isActive("code") ||
    editor.isActive("link")
  )
    return null;
  const text = $from.parent.textBetween(0, $from.parentOffset, undefined, "\ufffc");
  const match = detectTrigger(text, ["/", "@"]);
  if (!match || (match.char === "/" && match.start !== 0)) return null;
  return { ...match, start: $from.start() + match.start, end: $from.pos };
}

export type MarkdownEditorSuggestionsProps = {
  /** The application supplies people and their persistent profile URLs. */
  mentions?: readonly MarkdownEditorMention[] | ((query: string) => readonly MarkdownEditorMention[]);
  onMentionSelect?: (mention: MarkdownEditorMention) => void;
};

export function MarkdownEditorSuggestions({ mentions = [], onMentionSelect }: MarkdownEditorSuggestionsProps) {
  const { editor, editable: enabled, labels, isUrlAllowed } = useMarkdownEditor();
  const commands = useMemo(() => blockCommands(labels), [labels]);
  const controller = useTriggerMenu<EditorSuggestion>({
    triggers: [
      { char: "/", items: commands },
      { char: "@", items: mentions },
    ],
    onCommit: (item) => {
      if (!editor || !enabled || item.disabled) return;
      const match = readTrigger(editor);
      if (!match) return;
      const range = { from: match.start, to: match.end };
      if (match.char === "/" && item.command) item.command(editor.chain().focus().deleteRange(range)).run();
      if (match.char === "@" && item.href && isUrlAllowed(item.href, "link")) {
        editor
          .chain()
          .focus()
          .insertContentAt(range, [
            { type: "text", text: `@${item.label}`, marks: [{ type: "link", attrs: { href: item.href } }] },
            { type: "text", text: " " },
          ])
          .run();
        onMentionSelect?.({ ...item, href: item.href });
      }
    },
  });
  const report = useEffectEvent(() => {
    if (!editor || editor.isDestroyed) return;
    const match = enabled ? readTrigger(editor) : null;
    const coords = match ? editor.view.coordsAtPos(match.end) : null;
    controller.report(match, coords ? new DOMRect(coords.left, coords.top, 1, coords.bottom - coords.top) : null);
  });
  const handleKeyDown = useEffectEvent((event: KeyboardEvent) => {
    if (
      !editor ||
      editor.isDestroyed ||
      !enabled ||
      isComposingKey(event) ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      !readTrigger(editor)
    )
      return;
    if (controller.handleKeyDown(event.key)) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  });
  useEffect(() => {
    if (!editor || editor.isDestroyed || !enabled) return;
    const dom = editor.view.dom;
    editor.on("transaction", report).on("focus", report).on("blur", report);
    dom.addEventListener("keydown", handleKeyDown, true);
    return () => {
      editor.off("transaction", report).off("focus", report).off("blur", report);
      dom.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [editor, enabled]);

  const open = enabled && controller.open;
  useEffect(() => {
    if (!editor || editor.isDestroyed || !open) return;
    const owner = editor.view.dom.ownerDocument;
    owner.addEventListener("scroll", report, { capture: true, passive: true });
    owner.defaultView?.addEventListener("resize", report);
    return () => {
      owner.removeEventListener("scroll", report, true);
      owner.defaultView?.removeEventListener("resize", report);
    };
  }, [editor, open]);
  const { "aria-controls": controls, "aria-activedescendant": activeDescendant } = controller.inputAria;
  useEffect(() => {
    if (!editor || editor.isDestroyed || !enabled) return;
    const dom = editor.view.dom;
    const attributes = {
      "aria-autocomplete": "list",
      "aria-haspopup": "listbox",
      "aria-controls": controls,
      "aria-activedescendant": activeDescendant,
    };
    for (const [name, value] of Object.entries(attributes)) {
      if (value) dom.setAttribute(name, value);
      else dom.removeAttribute(name);
    }
    return () => {
      for (const name of Object.keys(attributes)) dom.removeAttribute(name);
    };
  }, [editor, enabled, controls, activeDescendant]);

  const label = controller.activeChar === "@" ? labels.mentions : labels.commands;
  const emptyLabel = controller.activeChar === "@" ? labels.noMentions : labels.noCommands;
  return (
    <>
      <LiveStatus message={open ? labels.suggestionCount(controller.items.length, label) : ""} />
      <TriggerMenu open={open} onOpenChange={controller.setOpen} anchorRect={controller.anchorRect} side="bottom">
        {controller.items.length === 0 ? <TriggerMenuEmpty>{emptyLabel}</TriggerMenuEmpty> : null}
        <TriggerMenuList id={controller.listId} aria-label={label}>
          {controller.items.map((item, index) => (
            <TriggerMenuItem
              key={item.id}
              id={controller.optionId(index)}
              active={index === controller.activeIndex}
              disabled={item.disabled || (item.href !== undefined && !isUrlAllowed(item.href, "link"))}
              onPointerMove={() => controller.setActiveIndex(index)}
              onClick={() => controller.select(item)}
            >
              <TriggerMenuIcon>{item.icon ?? <UserIcon />}</TriggerMenuIcon>
              <span className="min-w-0 flex-1 truncate">{item.label}</span>
              {item.description ? (
                <span
                  data-control-ui="markdown-editor"
                  data-control-family="markdown-editor"
                  data-slot="suggestion-description"
                  className="truncate"
                >
                  {item.description}
                </span>
              ) : null}
            </TriggerMenuItem>
          ))}
        </TriggerMenuList>
      </TriggerMenu>
    </>
  );
}

import type { ChainedCommands, Editor } from "@tiptap/core";
import { CellSelection, moveTableColumn, moveTableRow } from "@tiptap/pm/tables";
import { cellStart, type TableAxis, tableAt } from "./table-geometry";

export type ColumnAlign = "left" | "center" | "right";

/** The header row stays first: rows below it move, the header itself never does. */
export const firstMovable = (axis: TableAxis) => (axis === "row" ? 1 : 0);

export function lineCount(editor: Editor, tablePos: number, axis: TableAxis) {
  const found = tableAt(editor.state.doc, tablePos);
  if (!found) return 0;
  return axis === "row" ? found.map.height : found.map.width;
}

export function canMoveLine(count: number, axis: TableAxis, from: number, to: number) {
  return from !== to && from >= firstMovable(axis) && to >= firstMovable(axis) && to < count;
}

function lineStart(editor: Editor, tablePos: number, axis: TableAxis, index: number) {
  return axis === "row" ? cellStart(editor.state.doc, tablePos, index, 0) : cellStart(editor.state.doc, tablePos, 0, index);
}

export function selectLine(editor: Editor, tablePos: number, axis: TableAxis, index: number) {
  const position = lineStart(editor, tablePos, axis, index);
  if (position === null) return;
  const $cell = editor.state.doc.resolve(position);
  editor.view.dispatch(
    editor.state.tr.setSelection(axis === "row" ? CellSelection.rowSelection($cell) : CellSelection.colSelection($cell)),
  );
}

export function moveLine(editor: Editor, tablePos: number, axis: TableAxis, from: number, to: number) {
  const inside = cellStart(editor.state.doc, tablePos, 0, 0);
  if (inside === null || !canMoveLine(lineCount(editor, tablePos, axis), axis, from, to)) return false;
  const command = axis === "row" ? moveTableRow : moveTableColumn;
  return command({ from, to, pos: inside + 1, select: true })(editor.state, editor.view.dispatch);
}

export function runInCell(
  editor: Editor,
  tablePos: number,
  row: number,
  column: number,
  apply: (chain: ChainedCommands) => ChainedCommands,
) {
  const position = cellStart(editor.state.doc, tablePos, row, column);
  if (position === null) return;
  apply(
    editor
      .chain()
      .focus()
      .setTextSelection(position + 2),
  ).run();
}

export function alignColumn(editor: Editor, tablePos: number, column: number, align: ColumnAlign) {
  const position = cellStart(editor.state.doc, tablePos, 0, column);
  if (position === null) return;
  editor
    .chain()
    .focus()
    .command(({ tr }) => {
      tr.setSelection(CellSelection.colSelection(tr.doc.resolve(position)));
      return true;
    })
    .setCellAttribute("align", align)
    .run();
}

"use client";

import { PlusIcon } from "lucide-react";
import { type ReactNode, type RefObject, useRef, useState } from "react";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { useMarkdownEditor } from "./context";
import { lineCount, moveLine, runInCell } from "./table-commands";
import type { TableAxis } from "./table-geometry";
import { TableGrip } from "./table-grip";
import { useTableTarget } from "./use-table-target";

export function MarkdownEditorTableControls({ container }: { container: RefObject<HTMLDivElement | null> }) {
  const { editor, editable, labels } = useMarkdownEditor();
  const [menu, setMenu] = useState<TableAxis | null>(null);
  const [dragging, setDragging] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const controls = useRef<HTMLDivElement>(null);
  const { target, layout, setHover } = useTableTarget(editor, container, controls, editable, menu !== null || dragging);
  const status = <LiveStatus key="status" message={announcement} />;
  if (!(editor && target && layout)) return <TableControlsFrame frame={controls}>{status}</TableControlsFrame>;
  const live = editor;
  const { tablePos } = target;
  const rows = lineCount(live, tablePos, "row");
  const columns = lineCount(live, tablePos, "column");
  const visibleLeft = Math.max(layout.table.left, layout.clip.left);
  const visibleRight = Math.min(layout.table.left + layout.table.width, layout.clip.left + layout.clip.width);

  function move(axis: TableAxis, from: number, to: number) {
    if (!moveLine(live, tablePos, axis, from, to)) return;
    setHover({ tablePos, row: target?.row ?? 0, column: target?.column ?? 0, [axis]: to });
    setAnnouncement(axis === "row" ? labels.rowMoved(to) : labels.columnMoved(to + 1));
  }

  const grip = (axis: TableAxis) => (
    <TableGrip
      axis={axis}
      tablePos={tablePos}
      index={target[axis]}
      count={axis === "row" ? rows : columns}
      layout={layout}
      container={container}
      open={menu === axis}
      onOpenChange={(open) => setMenu(open ? axis : null)}
      onDraggingChange={setDragging}
      onMove={(from, to) => move(axis, from, to)}
    />
  );

  return (
    <TableControlsFrame frame={controls}>
      {grip("row")}
      {grip("column")}
      <Button
        type="button"
        variant="ghost"
        size="xs"
        className="absolute"
        data-markdown-table-add="row"
        aria-label={labels.addRow}
        style={{ top: layout.table.top + layout.table.height, left: visibleLeft, width: visibleRight - visibleLeft }}
        onClick={() => runInCell(live, tablePos, rows - 1, columns - 1, (chain) => chain.addRowAfter().goToNextCell())}
      >
        <PlusIcon aria-hidden="true" />
      </Button>
      <Button
        type="button"
        variant="ghost"
        size="xs"
        className="absolute"
        data-markdown-table-add="column"
        aria-label={labels.addColumn}
        style={{ top: layout.table.top, left: visibleRight, height: layout.table.height }}
        onClick={() => runInCell(live, tablePos, 0, columns - 1, (chain) => chain.addColumnAfter().goToNextCell())}
      >
        <PlusIcon aria-hidden="true" />
      </Button>
      {status}
    </TableControlsFrame>
  );
}

function TableControlsFrame({ frame, children }: { frame: RefObject<HTMLDivElement | null>; children: ReactNode }) {
  return (
    <div ref={frame} data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="table-controls">
      {children}
    </div>
  );
}

import type { Node as ProseMirrorNode, ResolvedPos } from "@tiptap/pm/model";
import { cellAround, TableMap } from "@tiptap/pm/tables";
import type { EditorView } from "@tiptap/pm/view";

export type TableAxis = "row" | "column";
export type TableTarget = { tablePos: number; row: number; column: number };
export type SurfaceBox = { top: number; left: number; width: number; height: number };
export type TableLayout = { table: SurfaceBox; clip: SurfaceBox; row: SurfaceBox; column: SurfaceBox };

export function tableTargetFrom($pos: ResolvedPos): TableTarget | null {
  const $cell = cellAround($pos);
  if (!$cell) return null;
  const tableStart = $cell.start(-1);
  const { left, top } = TableMap.get($cell.node(-1)).findCell($cell.pos - tableStart);
  return { tablePos: tableStart - 1, row: top, column: left };
}

export function tableTargetAt(view: EditorView, element: EventTarget | null): TableTarget | null {
  const cell = element instanceof Element ? element.closest("td, th") : null;
  if (!(cell && view.dom.contains(cell))) return null;
  return tableTargetFrom(view.state.doc.resolve(view.posAtDOM(cell, 0)));
}

export function tableAt(doc: ProseMirrorNode, tablePos: number) {
  const table = doc.nodeAt(tablePos);
  if (table?.type.spec.tableRole !== "table") return null;
  return { table, map: TableMap.get(table), tableStart: tablePos + 1 };
}

export function cellStart(doc: ProseMirrorNode, tablePos: number, row: number, column: number) {
  const found = tableAt(doc, tablePos);
  if (!found) return null;
  return found.tableStart + found.map.positionAt(row, column, found.table);
}

export function tableElement(view: EditorView, tablePos: number) {
  const wrapper = view.nodeDOM(tablePos);
  if (!(wrapper instanceof HTMLElement)) return null;
  const table = wrapper instanceof HTMLTableElement ? wrapper : wrapper.firstElementChild;
  return table instanceof HTMLTableElement ? table : null;
}

export function measureTable(surface: HTMLElement, table: HTMLTableElement, target: TableTarget): TableLayout | null {
  const row = table.rows[target.row];
  const head = table.rows[0]?.cells[target.column];
  if (!(row && head)) return null;
  const origin = surface.getBoundingClientRect();
  const box = (rect: DOMRect): SurfaceBox => ({
    top: rect.top - origin.top + surface.scrollTop,
    left: rect.left - origin.left + surface.scrollLeft,
    width: rect.width,
    height: rect.height,
  });
  return {
    table: box(table.getBoundingClientRect()),
    clip: box((table.parentElement ?? table).getBoundingClientRect()),
    row: box(row.getBoundingClientRect()),
    column: box(head.getBoundingClientRect()),
  };
}

function edges(table: HTMLTableElement, axis: TableAxis) {
  if (axis === "row") {
    const rows = Array.from(table.rows, (row) => row.getBoundingClientRect());
    return [...rows.map((rect) => rect.top), rows.at(-1)?.bottom ?? 0];
  }
  const cells = Array.from(table.rows[0]?.cells ?? [], (cell) => cell.getBoundingClientRect());
  return [...cells.map((rect) => rect.left), cells.at(-1)?.right ?? 0];
}

/** The gap a dragged row or column would land in; the header row's slot above it is never offered. */
export function nearestGap(table: HTMLTableElement, axis: TableAxis, client: number) {
  const lines = edges(table, axis);
  const first = axis === "row" ? 1 : 0;
  let gap = first;
  for (let index = first; index < lines.length; index += 1) {
    if (Math.abs(client - (lines[index] ?? 0)) < Math.abs(client - (lines[gap] ?? 0))) gap = index;
  }
  return { gap, line: lines[gap] ?? 0 };
}

export function indexForGap(from: number, gap: number) {
  return gap > from ? gap - 1 : gap;
}

export function isNear(rect: DOMRect, x: number, y: number, reach: number) {
  return x > rect.left - reach && x < rect.right + reach && y > rect.top - reach && y < rect.bottom + reach;
}

/** Converts a viewport coordinate on `axis` into the scrolled surface's coordinate space. */
export function toSurface(surface: HTMLElement, axis: TableAxis, client: number) {
  const origin = surface.getBoundingClientRect();
  return axis === "row" ? client - origin.top + surface.scrollTop : client - origin.left + surface.scrollLeft;
}

"use client";

import { GripHorizontalIcon, GripVerticalIcon } from "lucide-react";
import { type PointerEvent as ReactPointerEvent, type RefObject, useRef, useState } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/control-ui/ui/dropdown-menu";
import { useMarkdownEditor } from "./context";
import { alignColumn, type ColumnAlign, firstMovable, runInCell, selectLine } from "./table-commands";
import { indexForGap, nearestGap, type SurfaceBox, type TableAxis, type TableLayout, tableElement, toSurface } from "./table-geometry";

const DRAG_THRESHOLD = 4;
const MOVE_KEYS: Record<TableAxis, [back: string, forward: string]> = {
  row: ["ArrowUp", "ArrowDown"],
  column: ["ArrowLeft", "ArrowRight"],
};

type Press = { pointerId: number; x: number; y: number; moved: boolean };
type TableGripProps = {
  axis: TableAxis;
  tablePos: number;
  index: number;
  count: number;
  layout: TableLayout;
  container: RefObject<HTMLDivElement | null>;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDraggingChange: (dragging: boolean) => void;
  onMove: (from: number, to: number) => void;
};

function gripCenter(axis: TableAxis, layout: TableLayout) {
  if (axis === "row") return { top: layout.row.top + layout.row.height / 2, left: Math.max(layout.table.left, layout.clip.left) };
  return { top: layout.table.top, left: layout.column.left + layout.column.width / 2 };
}

const withinClip = (left: number, clip: SurfaceBox) => left >= clip.left && left <= clip.left + clip.width;

export function TableGrip({
  axis,
  tablePos,
  index,
  count,
  layout,
  container,
  open,
  onOpenChange,
  onDraggingChange,
  onMove,
}: TableGripProps) {
  const { editor, labels } = useMarkdownEditor();
  const [dropLine, setDropLine] = useState<{ gap: number; at: number } | null>(null);
  const press = useRef<Press | null>(null);
  const swallowClick = useRef(false);
  const openAtPress = useRef(false);
  const center = gripCenter(axis, layout);
  const movable = index >= firstMovable(axis);
  if (!editor || (axis === "column" && !withinClip(center.left, layout.clip))) return null;
  const live = editor;

  function startPress(event: ReactPointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) return;
    openAtPress.current = open;
    press.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, moved: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function beginDrag(current: Press, event: ReactPointerEvent<HTMLButtonElement>) {
    if (!movable || Math.hypot(event.clientX - current.x, event.clientY - current.y) < DRAG_THRESHOLD) return false;
    current.moved = true;
    onOpenChange(false);
    onDraggingChange(true);
    selectLine(live, tablePos, axis, index);
    return true;
  }

  function dragPress(event: ReactPointerEvent<HTMLButtonElement>) {
    const current = press.current;
    const surface = container.current;
    const table = tableElement(live.view, tablePos);
    if (!(current && surface && table) || current.pointerId !== event.pointerId) return;
    if (!(current.moved || beginDrag(current, event))) return;
    const client = axis === "row" ? event.clientY : event.clientX;
    const { gap, line } = nearestGap(table, axis, client);
    setDropLine({ gap, at: toSurface(surface, axis, line) });
  }

  function endPress(event: ReactPointerEvent<HTMLButtonElement>) {
    const current = press.current;
    if (!current || current.pointerId !== event.pointerId) return;
    press.current = null;
    swallowClick.current = current.moved;
    if (current.moved && dropLine) onMove(index, indexForGap(index, dropLine.gap));
    if (current.moved) onDraggingChange(false);
    setDropLine(null);
  }

  function cancelPress() {
    if (press.current?.moved) onDraggingChange(false);
    press.current = null;
    setDropLine(null);
  }

  function click() {
    const dragged = swallowClick.current;
    const wasOpen = openAtPress.current;
    swallowClick.current = false;
    openAtPress.current = false;
    if (dragged) return;
    if (!wasOpen) selectLine(live, tablePos, axis, index);
    onOpenChange(!wasOpen);
  }

  const [back, forward] = MOVE_KEYS[axis];
  const visibleLeft = Math.max(layout.table.left, layout.clip.left);
  const visibleRight = Math.min(layout.table.left + layout.table.width, layout.clip.left + layout.clip.width);

  return (
    <>
      <DropdownMenu
        open={open}
        onOpenChange={(next, details) => {
          if (details.reason === "trigger-press") return;
          if (next && details.event instanceof KeyboardEvent && details.event.altKey) return;
          onOpenChange(next);
        }}
      >
        <DropdownMenuTrigger
          variant="surface"
          size="xs"
          iconOnly
          className="absolute"
          data-markdown-table-grip={axis}
          data-dragging={dropLine ? "" : undefined}
          aria-label={axis === "row" ? labels.rowActions : labels.columnActions}
          aria-description={labels.tableGripDescription}
          style={center}
          onPointerDown={startPress}
          onPointerMove={dragPress}
          onPointerUp={endPress}
          onPointerCancel={cancelPress}
          onClick={click}
          onKeyDown={(event) => {
            if (!(event.altKey && (event.key === back || event.key === forward))) return;
            event.preventDefault();
            onMove(index, index + (event.key === back ? -1 : 1));
          }}
        >
          {axis === "row" ? <GripVerticalIcon aria-hidden="true" /> : <GripHorizontalIcon aria-hidden="true" />}
        </DropdownMenuTrigger>
        <DropdownMenuContent side={axis === "row" ? "left" : "top"} align="start" finalFocus={() => live.view.dom}>
          <TableGripMenu axis={axis} tablePos={tablePos} index={index} count={count} onMove={onMove} />
        </DropdownMenuContent>
      </DropdownMenu>
      {dropLine ? (
        <div
          data-control-ui="markdown-editor"
          data-control-family="markdown-editor"
          data-slot="table-drop-line"
          data-axis={axis}
          style={
            axis === "row"
              ? { top: dropLine.at, left: visibleLeft, width: visibleRight - visibleLeft }
              : { left: dropLine.at, top: layout.table.top, height: layout.table.height }
          }
        />
      ) : null}
    </>
  );
}

type TableGripMenuProps = Pick<TableGripProps, "axis" | "tablePos" | "index" | "count" | "onMove">;

function TableGripMenu({ axis, tablePos, index, count, onMove }: TableGripMenuProps) {
  const { editor, labels } = useMarkdownEditor();
  if (!editor) return null;
  const live = editor;
  const header = axis === "row" && index === 0;
  const inRow = (apply: Parameters<typeof runInCell>[4]) => () => runInCell(live, tablePos, index, 0, apply);
  const inColumn = (apply: Parameters<typeof runInCell>[4]) => () => runInCell(live, tablePos, 0, index, apply);
  const align = (value: ColumnAlign) => () => alignColumn(live, tablePos, index, value);

  return (
    <>
      {axis === "row" ? (
        <>
          <DropdownMenuItem disabled={header} onClick={inRow((chain) => chain.addRowBefore())}>
            {labels.insertRowAbove}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={inRow((chain) => chain.addRowAfter())}>{labels.insertRowBelow}</DropdownMenuItem>
        </>
      ) : (
        <>
          <DropdownMenuItem onClick={inColumn((chain) => chain.addColumnBefore())}>{labels.insertColumnLeft}</DropdownMenuItem>
          <DropdownMenuItem onClick={inColumn((chain) => chain.addColumnAfter())}>{labels.insertColumnRight}</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={align("left")}>{labels.alignLeft}</DropdownMenuItem>
          <DropdownMenuItem onClick={align("center")}>{labels.alignCenter}</DropdownMenuItem>
          <DropdownMenuItem onClick={align("right")}>{labels.alignRight}</DropdownMenuItem>
        </>
      )}
      <DropdownMenuSeparator />
      <DropdownMenuItem disabled={header || index === firstMovable(axis)} onClick={() => onMove(index, index - 1)}>
        {axis === "row" ? labels.moveRowUp : labels.moveColumnLeft}
      </DropdownMenuItem>
      <DropdownMenuItem disabled={header || index === count - 1} onClick={() => onMove(index, index + 1)}>
        {axis === "row" ? labels.moveRowDown : labels.moveColumnRight}
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      {axis === "row" ? (
        <DropdownMenuItem tone="danger" disabled={header} onClick={inRow((chain) => chain.deleteRow())}>
          {labels.deleteRow}
        </DropdownMenuItem>
      ) : (
        <DropdownMenuItem tone="danger" disabled={count === 1} onClick={inColumn((chain) => chain.deleteColumn())}>
          {labels.deleteColumn}
        </DropdownMenuItem>
      )}
    </>
  );
}

