type MarkdownEditorFormatAction = { label: string; Icon: typeof BoldIcon; active: boolean; run: () => void };

export function useMarkdownEditorFormatActions() {
  const { editor, labels } = useMarkdownEditor();
  const state = useEditorState({
    editor,
    selector: ({ editor: current }) => ({
      bold: Boolean(current?.isActive("bold")),
      italic: Boolean(current?.isActive("italic")),
      strike: Boolean(current?.isActive("strike")),
      code: Boolean(current?.isActive("code")),
      bulletList: Boolean(current?.isActive("bulletList")),
      orderedList: Boolean(current?.isActive("orderedList")),
      taskList: Boolean(current?.isActive("taskList")),
      blockquote: Boolean(current?.isActive("blockquote")),
      codeBlock: Boolean(current?.isActive("codeBlock")),
    }),
  });
  const focused = () => editor?.chain().focus();
  const marks: MarkdownEditorFormatAction[] = [
    { label: labels.bold, Icon: BoldIcon, active: Boolean(state?.bold), run: () => focused()?.toggleBold().run() },
    { label: labels.italic, Icon: ItalicIcon, active: Boolean(state?.italic), run: () => focused()?.toggleItalic().run() },
    { label: labels.strikethrough, Icon: StrikethroughIcon, active: Boolean(state?.strike), run: () => focused()?.toggleStrike().run() },
    { label: labels.inlineCode, Icon: CodeIcon, active: Boolean(state?.code), run: () => focused()?.toggleCode().run() },
  ];
  const blocks: MarkdownEditorFormatAction[] = [
    { label: labels.bulletList, Icon: ListIcon, active: Boolean(state?.bulletList), run: () => focused()?.toggleBulletList().run() },
    {
      label: labels.orderedList,
      Icon: ListOrderedIcon,
      active: Boolean(state?.orderedList),
      run: () => focused()?.toggleOrderedList().run(),
    },
    { label: labels.taskList, Icon: ListChecksIcon, active: Boolean(state?.taskList), run: () => focused()?.toggleTaskList().run() },
    { label: labels.quote, Icon: QuoteIcon, active: Boolean(state?.blockquote), run: () => focused()?.toggleBlockquote().run() },
    { label: labels.codeBlock, Icon: SquareCodeIcon, active: Boolean(state?.codeBlock), run: () => focused()?.toggleCodeBlock().run() },
  ];
  return { marks, blocks };
}

export function MarkdownEditorFormatButton({
  action,
  onMouseDown,
}: {
  action: MarkdownEditorFormatAction;
  onMouseDown?: MouseEventHandler<HTMLButtonElement>;
}) {
  const { editable } = useMarkdownEditor();
  const { label, Icon, active, run } = action;
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <ToolbarButton
            type="button"
            iconOnly
            aria-label={label}
            aria-pressed={active}
            disabled={!editable}
            onMouseDown={onMouseDown}
            onClick={run}
          />
        }
      >
        <Icon aria-hidden="true" />
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

function MarkdownEditorHistoryButton({
  label,
  Icon,
  disabled,
  onClick,
}: {
  label: string;
  Icon: typeof UndoIcon;
  disabled: boolean;
  onClick: () => void;
}) {
  return (
    <Tooltip>
      <TooltipTrigger render={<ToolbarButton type="button" iconOnly aria-label={label} disabled={disabled} onClick={onClick} />}>
        <Icon aria-hidden="true" />
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

export function MarkdownEditorToolbar({ children }: { children?: ReactNode }) {
  const { editor, disabled, editable, labels, source, sourceRequired, setSource, uploads } = useMarkdownEditor();
  const { marks, blocks } = useMarkdownEditorFormatActions();
  const history = useEditorState({
    editor,
    selector: ({ editor: current }) => ({ undo: current?.can().undo(), redo: current?.can().redo() }),
  });
  return (
    <TooltipProvider>
      <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="toolbar">
        <ScrollArea lockAxis="y" mask={false} blur={false}>
          <Toolbar aria-label={labels.toolbar} chrome="embedded" className="flex w-max min-w-full">
            <MarkdownEditorHeading />
            <ToolbarSeparator />
            {[...marks, ...blocks].map((action) => (
              <MarkdownEditorFormatButton key={action.label} action={action} onMouseDown={(event) => event.preventDefault()} />
            ))}
            <MarkdownEditorLink />
            <MarkdownEditorImage />
            <ToolbarSeparator />
            <MarkdownEditorHistoryButton
              label={labels.undo}
              Icon={UndoIcon}
              disabled={!editable || !history?.undo}
              onClick={() => editor?.chain().focus().undo().run()}
            />
            <MarkdownEditorHistoryButton
              label={labels.redo}
              Icon={RedoIcon}
              disabled={!editable || !history?.redo}
              onClick={() => editor?.chain().focus().redo().run()}
            />
            <ToolbarButton
              type="button"
              aria-pressed={source}
              disabled={disabled || !editor || sourceRequired || uploads.length > 0}
              onClick={() => setSource(!source)}
            >
              {labels.source}
            </ToolbarButton>
            {children}
          </Toolbar>
        </ScrollArea>
      </div>
    </TooltipProvider>
  );
}

export function MarkdownEditorHeading() {
  const { editor, editable, labels } = useMarkdownEditor();
  const level = useEditorState({
    editor,
    selector: ({ editor: activeEditor }) =>
      activeEditor?.isActive("heading") ? String(activeEditor.getAttributes("heading").level) : "paragraph",
  });
  const current = level && level !== "paragraph" ? labels.headingShort(Number(level)) : labels.text;
  return (
    <DropdownMenu>
      <ToolbarButton type="button" aria-label={labels.textStyle(current)} disabled={!editable} render={<DropdownMenuTrigger />}>
        <span>{current}</span>
        <ChevronDownIcon aria-hidden="true" />
      </ToolbarButton>
      <DropdownMenuContent finalFocus={() => editor?.view.dom ?? true}>
        <DropdownMenuRadioGroup
          value={level ?? "paragraph"}
          onValueChange={(value) => {
            if (!editor || !editable) return;
            const heading = ([1, 2, 3, 4, 5, 6] as const).find((item) => String(item) === value);
            if (heading) editor.chain().focus().setHeading({ level: heading }).run();
            else editor.chain().focus().setParagraph().run();
          }}
        >
          <DropdownMenuRadioItem value="paragraph" closeOnClick>
            {labels.paragraph}
          </DropdownMenuRadioItem>
          {[1, 2, 3, 4, 5, 6].map((item) => (
            <DropdownMenuRadioItem key={item} value={String(item)} closeOnClick>
              {labels.heading(item)}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function MarkdownEditorUrlField({
  label,
  error,
  invalid,
  ...props
}: Omit<ComponentProps<typeof Input>, "id"> & { label: string; error: string; invalid: boolean }) {
  const inputId = useId();
  const errorId = useId();
  return (
    <>
      <Label htmlFor={inputId}>{label}</Label>
      <Input id={inputId} aria-invalid={invalid || undefined} aria-describedby={invalid ? errorId : undefined} {...props} />
      {invalid ? (
        <Text as="p" id={errorId} role="alert" size="caption" tone="danger">
          {error}
        </Text>
      ) : null}
    </>
  );
}

export function MarkdownEditorLink() {
  const { editor, editable, labels, isUrlAllowed } = useMarkdownEditor();
  const linked = useEditorState({ editor, selector: ({ editor: current }) => Boolean(current?.isActive("link")) });
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [checked, setChecked] = useState(false);
  const href = url.trim();
  const valid = isUrlAllowed(href, "link");
  function apply() {
    if (!valid || !editable) return;
    editor?.chain().focus().extendMarkRange("link").setLink({ href }).run();
    setOpen(false);
  }
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        if (!next) return;
        setUrl(editor?.getAttributes("link").href ?? "");
        setChecked(false);
      }}
    >
      <Tooltip>
        <TooltipTrigger
          render={<ToolbarButton type="button" iconOnly aria-label={labels.link} disabled={!editable} render={<PopoverTrigger />} />}
        >
          <LinkIcon aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent>{labels.link}</TooltipContent>
      </Tooltip>
      <PopoverContent
        finalFocus={() => editor?.view.dom ?? true}
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter" && event.target instanceof HTMLInputElement && !event.nativeEvent.isComposing) {
            event.preventDefault();
            event.stopPropagation();
            setChecked(true);
            apply();
          }
        }}
      >
        <PopoverTitle>{labels.link}</PopoverTitle>
        <MarkdownEditorUrlField
          label={labels.linkUrl}
          error={labels.linkInvalid}
          invalid={checked && href !== "" && !valid}
          value={url}
          onChange={(event) => setUrl(event.target.value)}
          onBlur={() => setChecked(true)}
          placeholder="https://example.com"
        />
        <div className="flex gap-2">
          <Button type="button" disabled={!valid || !editable} onClick={apply}>
            {labels.applyLink}
          </Button>
          <Button
            type="button"
            variant="ghost"
            disabled={!editable || !linked}
            onClick={() => {
              editor?.chain().focus().extendMarkRange("link").unsetLink().run();
              setOpen(false);
            }}
          >
            {labels.removeLink}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorImage() {
  const { editor, editable, labels, canUpload, upload, isUrlAllowed } = useMarkdownEditor();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [alt, setAlt] = useState("");
  const [checked, setChecked] = useState(false);
  const altId = useId();
  const fileInput = useRef<HTMLInputElement>(null);
  const src = url.trim();
  const valid = isUrlAllowed(src, "image");
  function insert() {
    if (!valid || !editable) return;
    editor?.chain().focus().setImage({ src, alt }).run();
    setOpen(false);
    setUrl("");
    setAlt("");
    setChecked(false);
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger
          render={<ToolbarButton type="button" iconOnly aria-label={labels.image} disabled={!editable} render={<PopoverTrigger />} />}
        >
          <ImageIcon aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent>{labels.image}</TooltipContent>
      </Tooltip>
      <PopoverContent
        finalFocus={() => editor?.view.dom ?? true}
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter" && event.target instanceof HTMLInputElement && !event.nativeEvent.isComposing) {
            event.preventDefault();
            event.stopPropagation();
            setChecked(true);
            insert();
          }
        }}
      >
        <PopoverTitle>{labels.image}</PopoverTitle>
        <MarkdownEditorUrlField
          label={labels.imageUrl}
          error={labels.imageInvalid}
          invalid={checked && src !== "" && !valid}
          value={url}
          onChange={(event) => setUrl(event.target.value)}
          onBlur={() => setChecked(true)}
          placeholder="https://example.com/image.png"
        />
        <Label htmlFor={altId}>{labels.imageDescription}</Label>
        <Input id={altId} value={alt} onChange={(event) => setAlt(event.target.value)} />
        <Button type="button" disabled={!valid || !editable} onClick={insert}>
          {labels.image}
        </Button>
        {canUpload ? (
          <>
            <input
              ref={fileInput}
              type="file"
              accept={markdownImageTypes.join(",")}
              multiple
              hidden
              onChange={(event) => {
                upload(Array.from(event.target.files ?? []));
                event.target.value = "";
                setOpen(false);
              }}
            />
            <Button type="button" variant="ghost" disabled={!editable} onClick={() => fileInput.current?.click()}>
              {labels.uploadImages}
            </Button>
          </>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorUploads() {
  const { uploads, uploadError, retryUpload, removeUpload, disabled, labels } = useMarkdownEditor();
  return (
    <>
      {uploadError ? (
        <Text as="p" role="alert">
          {uploadError}
        </Text>
      ) : null}
      {uploads.length > 0 ? (
        <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="uploads">
          <ChatComposerAttachments label={labels.uploads}>
            {uploads.map((item) => (
              <ChatComposerAttachment
                key={item.id}
                file={item.file}
                status={item.status}
                progress={item.progress}
                onRemove={disabled ? undefined : () => removeUpload(item.id)}
                removeLabel={labels.removeUpload(item.file.name)}
              />
            ))}
          </ChatComposerAttachments>
          {uploads
            .filter((item) => item.status === "error")
            .map((item) => (
              <div key={item.id} role="alert" className="flex items-center gap-2">
                <span>
                  {item.file.name}: {item.error}
                </span>
                <Button type="button" size="xs" disabled={disabled} onClick={() => retryUpload(item.id)}>
                  {labels.retryUpload}
                </Button>
              </div>
            ))}
        </div>
      ) : null}
    </>
  );
}

import type { Editor } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "./extensions";

export type MarkdownImage = { url: string; alt?: string; title?: string };
export type MarkdownImageUploader = (
  file: File,
  options: { signal: AbortSignal; onProgress: (progress: number) => void },
) => Promise<MarkdownImage>;
export type MarkdownImageUpload = {
  id: string;
  file: File;
  status: "uploading" | "error";
  progress?: number;
  error?: string;
};

export function findImageUpload(document: ProseMirrorNode, id: string) {
  let position: number | undefined;
  document.descendants((node, pos) => {
    if (node.type.name === "imageUpload" && node.attrs.id === id) position = pos;
  });
  return position;
}

export function completeImageUpload(
  editor: Editor,
  id: string,
  image: MarkdownImage,
  fallbackAlt: string,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
) {
  if (!isUrlAllowed(image.url, "image")) {
    throw new Error(
      isUrlAllowed === persistentUrlPolicy
        ? "The upload must return a permanent HTTP(S) or root-relative image URL."
        : "The upload returned an image URL this editor does not accept.",
    );
  }
  const position = findImageUpload(editor.state.doc, id);
  if (position === undefined) return;
  const imageType = editor.schema.nodes.image;
  const paragraphType = editor.schema.nodes.paragraph;
  if (!imageType || !paragraphType) throw new Error("Image uploads require image and paragraph nodes.");
  const node = imageType.create({ src: image.url, alt: image.alt ?? fallbackAlt, title: image.title ?? null });
  editor.view.dispatch(
    editor.state.tr.replaceWith(position, position + 1, paragraphType.create(null, node)).setMeta("addToHistory", false),
  );
}

export const markdownImageTypes = ["image/png", "image/jpeg", "image/gif", "image/webp", "image/avif"];

import type { Editor } from "@tiptap/core";
import { useEffect, useId, useRef, useState } from "react";
import { defaultMarkdownEditorLabels, type MarkdownEditorLabels } from "./context";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "./extensions";
import { completeImageUpload, findImageUpload, type MarkdownImageUpload, type MarkdownImageUploader, markdownImageTypes } from "./uploads";

export function useImageUploads(
  editor: Editor | null,
  uploader: MarkdownImageUploader | undefined,
  maxImageBytes: number,
  isUrlAllowed: MarkdownUrlPolicy = persistentUrlPolicy,
  labels: Pick<MarkdownEditorLabels, "uploadFailed" | "uploadRejected"> = defaultMarkdownEditorLabels,
) {
  const [uploads, setUploads] = useState<MarkdownImageUpload[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const uploadPrefix = useId();
  const nextId = useRef(0);
  const jobs = useRef(new Map<string, { file: File; controller: AbortController }>());

  function discard(id: string) {
    jobs.current.get(id)?.controller.abort();
    jobs.current.delete(id);
    setUploads((current) => current.filter((item) => item.id !== id));
  }

  function cancelAll() {
    for (const job of jobs.current.values()) job.controller.abort();
    jobs.current.clear();
    setUploads([]);
  }

  useEffect(() => {
    const activeJobs = jobs.current;
    return () => {
      for (const job of activeJobs.values()) job.controller.abort();
      activeJobs.clear();
    };
  }, []);

  useEffect(() => {
    if (!editor) return;
    const prune = () => {
      for (const id of jobs.current.keys()) {
        if (findImageUpload(editor.state.doc, id) === undefined) {
          jobs.current.get(id)?.controller.abort();
          jobs.current.delete(id);
          setUploads((current) => current.filter((item) => item.id !== id));
        }
      }
    };
    editor.on("update", prune);
    return () => {
      editor.off("update", prune);
    };
  }, [editor]);

  async function run(id: string, file: File) {
    if (!editor || !uploader) return;
    const controller = new AbortController();
    jobs.current.set(id, { file, controller });
    setUploads((current) => [...current.filter((item) => item.id !== id), { id, file, status: "uploading" }]);
    try {
      const image = await uploader(file, {
        signal: controller.signal,
        onProgress: (progress) => {
          if (controller.signal.aborted || !Number.isFinite(progress)) return;
          setUploads((current) =>
            current.map((item) => (item.id === id ? { ...item, progress: Math.max(0, Math.min(100, progress)) } : item)),
          );
        },
      });
      if (controller.signal.aborted || editor.isDestroyed) return;
      completeImageUpload(editor, id, image, file.name, isUrlAllowed);
      discard(id);
    } catch (error) {
      if (controller.signal.aborted) return;
      setUploads((current) =>
        current.map((item) =>
          item.id === id
            ? {
                ...item,
                status: "error",
                error: error instanceof Error ? error.message : labels.uploadFailed,
              }
            : item,
        ),
      );
    }
  }

  function upload(files: File[], position?: number) {
    if (!editor || !uploader || !editor.isEditable) return;
    setUploadError(null);
    let insertAt = position ?? editor.state.selection.to;
    for (const file of files) {
      if (!markdownImageTypes.includes(file.type) || file.size > maxImageBytes) {
        setUploadError(labels.uploadRejected(Math.round(maxImageBytes / 1024 / 1024)));
        continue;
      }
      const id = `${uploadPrefix}-${nextId.current++}`;
      editor
        .chain()
        .focus()
        .insertContentAt(insertAt, { type: "imageUpload", attrs: { id, name: file.name } })
        .run();
      insertAt = editor.state.selection.to;
      void run(id, file);
    }
  }

  function removeUpload(id: string) {
    discard(id);
    if (!editor) return;
    const position = findImageUpload(editor.state.doc, id);
    if (position !== undefined) editor.view.dispatch(editor.state.tr.delete(position, position + 1).setMeta("addToHistory", false));
  }

  function retryUpload(id: string) {
    const job = jobs.current.get(id);
    if (job) {
      job.controller.abort();
      void run(id, job.file);
    }
  }

  return { uploads, uploadError, upload, retryUpload, removeUpload, cancelAll };
}

"use client";

import type { Editor } from "@tiptap/core";
import type { Transaction } from "@tiptap/pm/state";
import type { EditorView } from "@tiptap/pm/view";
import { type Dispatch, type RefObject, type SetStateAction, useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  isNear,
  measureTable,
  type TableLayout,
  type TableTarget,
  tableAt,
  tableElement,
  tableTargetAt,
  tableTargetFrom,
} from "./table-geometry";

const HOVER_REACH = 28;

const sameTarget = (a: TableTarget | null, b: TableTarget | null) =>
  a === b || (a !== null && b !== null && a.tablePos === b.tablePos && a.row === b.row && a.column === b.column);

function mapTarget(current: TableTarget | null, transaction: Transaction): TableTarget | null {
  if (!current) return null;
  const tablePos = transaction.mapping.map(current.tablePos, -1);
  const found = tableAt(transaction.doc, tablePos);
  if (!found) return null;
  return { tablePos, row: Math.min(current.row, found.map.height - 1), column: Math.min(current.column, found.map.width - 1) };
}

function hoverFor(view: EditorView, current: TableTarget | null, event: MouseEvent) {
  const next = tableTargetAt(view, event.target);
  if (next) return sameTarget(current, next) ? current : next;
  const rect = current ? tableElement(view, current.tablePos)?.getBoundingClientRect() : undefined;
  return rect && isNear(rect, event.clientX, event.clientY, HOVER_REACH) ? current : null;
}

type TableTargetState = {
  target: TableTarget | null;
  layout: TableLayout | null;
  setHover: Dispatch<SetStateAction<TableTarget | null>>;
};

/** The table cell the controls attach to: the hovered cell, else the caret's cell while editing or while a grip is held. */
export function useTableTarget(
  editor: Editor | null,
  container: RefObject<HTMLDivElement | null>,
  controls: RefObject<HTMLDivElement | null>,
  enabled: boolean,
  holding: boolean,
): TableTargetState {
  const [hover, setHover] = useState<TableTarget | null>(null);
  const [revision, setRevision] = useState(0);
  const [layout, setLayout] = useState<TableLayout | null>(null);
  const holdingRef = useRef(holding);
  holdingRef.current = holding;

  useEffect(() => {
    const surface = container.current;
    if (!editor || editor.isDestroyed || !surface || !enabled) return;
    const { view } = editor;
    let frame = 0;
    let latest: MouseEvent | null = null;
    const insideControls = (node: unknown) => node instanceof Node && controls.current?.contains(node) === true;
    function follow(event: MouseEvent) {
      if (holdingRef.current || insideControls(event.target)) return;
      setHover((current) => hoverFor(view, current, event));
    }
    function track(event: MouseEvent) {
      latest = event;
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        if (latest) follow(latest);
      });
    }
    function leave() {
      if (!(holdingRef.current || insideControls(document.activeElement))) setHover(null);
    }
    function remeasure() {
      setRevision((value) => value + 1);
    }
    function transacted({ transaction }: { transaction: Transaction }) {
      if (transaction.docChanged) setHover((current) => mapTarget(current, transaction));
      remeasure();
    }
    surface.addEventListener("mousemove", track);
    surface.addEventListener("mouseleave", leave);
    surface.addEventListener("scroll", remeasure, { capture: true, passive: true });
    window.addEventListener("resize", remeasure);
    editor.on("transaction", transacted).on("focus", remeasure).on("blur", remeasure);
    return () => {
      cancelAnimationFrame(frame);
      surface.removeEventListener("mousemove", track);
      surface.removeEventListener("mouseleave", leave);
      surface.removeEventListener("scroll", remeasure, { capture: true });
      window.removeEventListener("resize", remeasure);
      editor.off("transaction", transacted).off("focus", remeasure).off("blur", remeasure);
    };
  }, [editor, container, controls, enabled]);

  const live = editor && !editor.isDestroyed && enabled;
  const caret = live && (editor.isFocused || holding) ? tableTargetFrom(editor.state.selection.$from) : null;
  const target = live ? (hover ?? caret) : null;
  const tablePos = target?.tablePos;
  const row = target?.row;
  const column = target?.column;

  // biome-ignore lint/correctness/useExhaustiveDependencies: revision re-measures after scroll, resize and edits
  useLayoutEffect(() => {
    const surface = container.current;
    const table = editor && tablePos !== undefined ? tableElement(editor.view, tablePos) : null;
    if (!(surface && table && row !== undefined && column !== undefined && tablePos !== undefined)) {
      setLayout(null);
      return;
    }
    setLayout(measureTable(surface, table, { tablePos, row, column }));
  }, [editor, container, tablePos, row, column, revision]);

  return { target: layout ? target : null, layout, setHover };
}

