    gap: var(--cui-markdown-editor-gap);
  }
  :where([data-control-family="markdown-editor"] .tiptap [data-slot="task-checkbox"]) {
    display: inline-flex;
    align-items: center;
    block-size: 1lh;
    flex-shrink: 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap [data-slot="task-content"]) {
    flex: 1;
    min-inline-size: 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap blockquote) {
    border-inline-start: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
    padding-inline-start: var(--cui-markdown-editor-padding);
    color: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"] .tiptap :is(code, pre)) {
    font-family: var(--font-mono);
    background: var(--cui-markdown-editor-code-background);
    border-radius: var(--radius-sm);
  }
  :where([data-control-family="markdown-editor"] .tiptap pre) {
    padding: var(--cui-markdown-editor-padding);
    overflow: auto;
  }
  :where([data-control-family="markdown-editor"] .tiptap img[src]) {
    display: block;
    max-inline-size: 100%;
    block-size: auto;
    border-radius: var(--radius-sm);
  }
  :where([data-control-family="markdown-editor"] .tiptap .ProseMirror-selectednode) {
    outline: none;
    opacity: var(--_markdown-editor-node-opacity, 1);
  }
  :where([data-control-family="markdown-editor"][data-slot="content"]:focus-within .tiptap .ProseMirror-selectednode) {
    outline: var(--_markdown-editor-node-outline, var(--focus-ring-width) var(--focus-ring-style) var(--focus-ring));
    outline-offset: 2px;
  }
  :where(
    [data-control-family="markdown-editor"][data-slot="content"]:has(
      > [data-markdown-drag-handle]:is([data-pointer-selection], [data-lifted])
    )
  ) {
    --_markdown-editor-node-outline: none;
  }
  :where([data-control-family="markdown-editor"][data-slot="content"]:has(> [data-markdown-drag-handle][data-lifted])) {
    --_markdown-editor-node-opacity: 0.4;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-preview]) {
    position: fixed;
    inset-block-start: -10000px;
    inset-inline-start: -10000px;
    inline-size: max-content;
    max-inline-size: none;
    min-block-size: 0;
    max-block-size: calc(var(--spacing) * 96);
    padding: calc(var(--spacing) * 1.5) calc(var(--spacing) * 3);
    overflow: hidden;
    contain: layout paint;
    border: var(--control-rim-width) solid var(--border);
    border-radius: var(--radius-panel);
    background: var(--card);
    color: var(--card-foreground);
    pointer-events: none;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-preview] > *) {
    margin: 0;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-preview][data-clipped]) {
    mask-image: linear-gradient(to bottom, oklch(0 0 0) calc(100% - var(--spacing) * 12), transparent);
  }
  :where([data-control-family="markdown-editor"] .prosemirror-dropcursor-block) {
    border-radius: 9999px;
    background: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"] .tiptap [data-image-upload]) {
    padding: var(--cui-markdown-editor-padding);
    border: var(--cui-markdown-editor-border-width) dashed var(--cui-markdown-editor-border-color);
    color: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"][data-slot="suggestion-description"]) {
    color: var(--muted-foreground);
  }
  @keyframes cui-markdown-editor-bubble-enter {
    from {
      opacity: 0;
      scale: 0.96;
    }
  }
}

